import 'package:flutter/material.dart';
import '../services/supabase_service.dart';
import '../repositories/profile_repository.dart';
import 'edit_profile_screen.dart';

class ProfileScreen extends StatefulWidget{const ProfileScreen({super.key});@override State<ProfileScreen> createState()=>_S();}
class _S extends State<ProfileScreen>{Future<Map<String,dynamic>?> load()async{final id=SupabaseService.client.auth.currentUser!.id;return await SupabaseService.client.from('profiles').select().eq('id',id).maybeSingle();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('My profile'),actions:[IconButton(onPressed:()=>Navigator.pushNamed(c,'/connections'),icon:const Icon(Icons.people_alt_outlined)),IconButton(onPressed:()=>SupabaseService.client.auth.signOut(),icon:const Icon(Icons.logout))]),body:FutureBuilder<Map<String,dynamic>?>(future:load(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final p=s.data!;return RefreshIndicator(onRefresh:()async=>setState((){}),child:ListView(padding:const EdgeInsets.all(20),children:[const CircleAvatar(radius:44,child:Icon(Icons.person,size:44)),const SizedBox(height:14),Text('${p['full_name']??''}',style:const TextStyle(fontSize:26,fontWeight:FontWeight.bold)),Text('@${p['username']??''}'),const SizedBox(height:14),Text('${p['bio']??''}'),const Divider(height:30),Text('African citizenship: ${p['african_citizenship']??'-'}'),Text('Current country: ${p['current_country']??'-'}'),Text('Languages: ${List<String>.from(p['languages']??const[]).join(', ')}'),Text('Skills: ${List<String>.from(p['skills']??const[]).join(', ')}'),Text('Interests: ${List<String>.from(p['interests']??const[]).join(', ')}'),Text('Verification: ${p['verification_status']??'unverified'}'),const SizedBox(height:20),FilledButton.icon(onPressed:()async{final changed=await Navigator.push(c,MaterialPageRoute(builder:(_)=>EditProfileScreen(profile:p)));if(changed==true&&mounted)setState((){});},icon:const Icon(Icons.edit),label:const Text('Edit profile')),OutlinedButton.icon(onPressed:()=>Navigator.pushNamed(c,'/connections'),icon:const Icon(Icons.people),label:const Text('Connections'))]));}));}}